WITH flattened AS (SELECT id, host, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, attr_value), flattened_attrs AS (SELECT host, attr_key, attr_value, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS flag_bit1 FROM flattened), filtered AS (SELECT *, TRIM(host) AS clean_host FROM flattened_attrs WHERE attr_key IS NOT NULL AND attr_key IS DISTINCT FROM 'region'), base AS (SELECT attr_key, attr_value, status_code_high, flag_bit1, CONCAT(host, '/', attr_key) AS host_attr_key FROM filtered WHERE status_code_high <= 1), with_windows AS (SELECT *, MAX(flag_bit1) OVER (PARTITION BY attr_key) AS attr_key_max_flag_bit1 FROM base), summary AS (SELECT attr_key, ROUND(AVG(attr_key_max_flag_bit1), 2) AS avg_attr_key_max_flag_bit1, MIN(status_code_high) AS min_status_code_high, COUNT(*) AS row_count, COUNT(CASE WHEN attr_key = 'region' THEN 1 END) AS region_count, ROUND(SUM(status_code_high) / NULLIF(COUNT(CASE WHEN attr_key = 'trace' THEN 1 END), 0), 2) AS status_code_high_per_trace FROM with_windows GROUP BY 1) SELECT attr_key, min_status_code_high, row_count, region_count, status_code_high_per_trace FROM summary ORDER BY row_count, status_code_high_per_trace DESC
